#     action_fluent    `-> Name[i].method(args) { blk }`    -> { type: action_edge }
#     action_bare      `-> Name[i]`                         -> { type: action_edge }
#     blind_block      `=> Child { code }`                  -> { type: blind_edge }
#     blind_fluent     `=> Child.method(args) { blk }`      -> { type: blind_edge }
